async () => {
  await document.fonts.ready;
  const f = document.getElementById('flyer');
  const r = (el)=>{const b=el.getBoundingClientRect();return {t:Math.round(b.top),b:Math.round(b.bottom),l:Math.round(b.left),r:Math.round(b.right)};};
  const out = {
    interLoaded: document.fonts.check('800 76px Inter'),
    flyer: r(f),
    scrollH: f.scrollHeight, clientH: f.clientHeight,
    headline: r(document.querySelector('.headline')),
    photo: r(document.querySelector('.photoband')),
    cands: r(document.querySelector('.cands')),
    candBoxes: [...document.querySelectorAll('.cand')].map(r),
    nmBoxes: [...document.querySelectorAll('.cand .nm')].map(e=>({...r(e), sw:e.scrollWidth, cw:e.clientWidth})),
    cta: r(document.querySelector('.cta')),
    ctaSpan: r(document.querySelector('.cta span')),
    steps: [...document.querySelectorAll('.step')].map(e=>({...r(e), sw:e.querySelector('span').scrollWidth, cw:e.querySelector('span').clientWidth})),
    footer: {...r(document.querySelector('.footer')), sw:document.querySelector('.footer').scrollWidth, cw:document.querySelector('.footer').clientWidth},
    imgNat: (()=>{const i=document.querySelector('.photoband img');return [i.naturalWidth,i.naturalHeight,Math.round(i.getBoundingClientRect().width),Math.round(i.getBoundingClientRect().height)];})()
  };
  return JSON.stringify(out,null,1);
}

